D(A,linewidth(2.pt)); D(B,linewidth(2.pt)); D((-0.54,2.94),linewidth(2.pt)); D(C,linewidth(2.pt)); D(D,linewidth(2.pt)); D((0.98,4.46),linewidth(2.pt)); D((0.98,3.7),linewidth(2.pt)); D((0.98,2.94),linewidth(2.pt)); D((0.22,2.94),linewidth(2.pt)); D(F,linewidth(4.pt)+blue); D(G,linewidth(4.pt)+blue); D(H,linewidth(4.pt)+blue); D(I,linewidth(4.pt)+blue); 
